# GPX to JSON Conversion in Python

## Overview
GPX (GPS Exchange Format) is an XML-based format for storing GPS waypoints, routes, and tracks. Converting GPX to JSON makes data more accessible for web applications and APIs.

## Required Libraries
```python
pip install gpxpy
```

## Basic Conversion Method

```python
import gpxpy
import json
from typing import Dict, List, Any

def gpx_to_json(gpx_file_path: str) -> str:
    with open(gpx_file_path, 'r') as gpx_file:
        gpx = gpxpy.parse(gpx_file)

    data = {
        'metadata': {
            'name': gpx.name,
            'description': gpx.description
        },
        'waypoints': [],
        'tracks': [],
        'routes': []
    }

    for waypoint in gpx.waypoints:
        data['waypoints'].append({
            'name': waypoint.name,
            'latitude': waypoint.latitude,
            'longitude': waypoint.longitude,
            'elevation': waypoint.elevation
        })

    for track in gpx.tracks:
        track_data = {
            'name': track.name,
            'segments': []
        }
        for segment in track.segments:
            segment_points = []
            for point in segment.points:
                segment_points.append({
                    'lat': point.latitude,
                    'lon': point.longitude,
                    'ele': point.elevation,
                    'time': point.time.isoformat() if point.time else None
                })
            track_data['segments'].append(segment_points)
        data['tracks'].append(track_data)

    return json.dumps(data, indent=2)

# Usage
json_output = gpx_to_json('route.gpx')
print(json_output)
```

## Advanced Conversion with Statistics

```python
def gpx_to_json_advanced(gpx_file_path: str) -> Dict[str, Any]:
    with open(gpx_file_path, 'r') as gpx_file:
        gpx = gpxpy.parse(gpx_file)

    total_distance = gpx.length_2d()
    total_elevation_gain = 0

    data = {
        'metadata': {
            'name': gpx.name or 'Unnamed Route',
            'description': gpx.description,
            'statistics': {
                'total_distance_m': total_distance,
                'total_distance_km': total_distance / 1000,
                'elevation_gain_m': total_elevation_gain
            }
        },
        'features': []
    }

    for track_idx, track in enumerate(gpx.tracks):
        for segment_idx, segment in enumerate(track.segments):
            points = []
            prev_elevation = None

            for point in segment.points:
                if prev_elevation and point.elevation:
                    gain = max(0, point.elevation - prev_elevation)
                    total_elevation_gain += gain

                points.append({
                    'type': 'Point',
                    'coordinates': [point.longitude, point.latitude, point.elevation],
                    'properties': {
                        'time': point.time.isoformat() if point.time else None,
                        'name': point.name
                    }
                })
                prev_elevation = point.elevation

            if points:
                data['features'].append({
                    'type': 'Feature',
                    'geometry': {
                        'type': 'LineString',
                        'coordinates': [[p['coordinates'][0], p['coordinates'][1]] for p in points]
                    },
                    'properties': {
                        'track': track.name or f'Track {track_idx}',
                        'segment': segment_idx
                    }
                })

    data['metadata']['statistics']['elevation_gain_m'] = total_elevation_gain
    return data

# Usage
result = gpx_to_json_advanced('route.gpx')
json_str = json.dumps(result, indent=2)
print(json_str)
```

## Example Output
```json
{
  "metadata": {
    "name": "My Route",
    "description": "Weekend hiking",
    "statistics": {
      "total_distance_km": 12.5,
      "elevation_gain_m": 450
    }
  },
  "features": [
    {
      "type": "Feature",
      "geometry": {
        "type": "LineString",
        "coordinates": [[10.123, 50.456], [10.124, 50.457]]
      },
      "properties": {
        "track": "Track 1",
        "segment": 0
      }
    }
  ]
}
```

## Handling Multiple Waypoints

```python
def extract_waypoints_to_json(gpx_file_path: str) -> str:
    with open(gpx_file_path, 'r') as f:
        gpx = gpxpy.parse(f)

    waypoints = [{
        'id': idx,
        'name': wp.name,
        'description': wp.description,
        'coords': {'lat': wp.latitude, 'lon': wp.longitude},
        'symbol': wp.symbol,
        'type': wp.type
    } for idx, wp in enumerate(gpx.waypoints, 1)]

    return json.dumps({'waypoints': waypoints}, indent=2)
```

This approach handles waypoints, tracks with multiple segments, and calculates route statistics efficiently.

